        JSON.stringify(CLAUDE_SESSION_SETTINGS),
        '--strict-mcp-config',
        '--disable-slash-commands',
        '--no-chrome',
        '--tools',
        'Read,Write,Edit,Glob,Grep',
        '--mcp-config',
